from rules import amount


def solve(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}

    # Filter before deduplication. Keep the last event when revisions tie.
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        if "id" in event:
            key = ("id", event["id"])
        else:
            key = ("anonymous", position)
        revision = event.get("revision", 0)
        previous = winners.get(key)
        if previous is None or revision >= previous[0]:
            winners[key] = (revision, position, event)

    balances = dict(data.get("opening", {}))
    for _, _, event in winners.values():
        if event.get("void", False):
            continue
        key = f"{event.get('account', 'default')}|{event.get('currency', 'USD')}"
        balances[key] = balances.get(key, 0) + amount(event, data["rounding"])

    return {"balances": balances}

def _round_divide(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def amount(event, mode):
    gross = event["price"] * event.get("quantity", 1)
    discount_bp = min(10000, max(0, event.get("discount_bp", 0)))
    net = _round_divide(gross * (10000 - discount_bp), 10000, mode)
    tax = _round_divide(net * event.get("tax_bp", 0), 10000, mode)
    total = net + tax
    if event.get("kind") == "refund":
        return -total
    return total
